const files=['packages/core/src/mission/workflow-ir.js','apps/pc-agent/src/adapters/workflow/local-workflow-adapter.js','packages/core/src/mission/natural-workflow-compiler.js','packages/core/src/mission/mission-local-workflow-constraints.js','packages/core/src/mission/mission-theology-review-result.js','packages/core/src/mission/mission-runtime.js','tests/natural-theology-review.test.js','docs/theology-research-review.md'];
